import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class ReportComponent extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      fromDate: '2026-10-01',
      toDate: '2026-11-01',
      stats: {
        revenue: 0,
        orders: 0,
        customers: 0,
        products: 0
      },
      topProducts: []
    };
  }

  componentDidMount() {
    this.apiGetReports();
    this.apiGetTopProducts();
  }

  // Lấy dữ liệu báo cáo thống kê từ Server
  apiGetReports = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/reports', config).then((res) => {
      if (res.data) {
        this.setState({ stats: res.data });
      }
    });
  };

  // Lấy danh sách món ăn bán chạy nhất
  apiGetTopProducts = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/products', config).then((res) => {
      // Lấy 4 món ăn đầu tiên làm dữ liệu mẫu bán chạy
      this.setState({ topProducts: res.data.slice(0, 4) });
    });
  };

  btnFilterClick = (e) => {
    e.preventDefault();
    this.apiGetReports();
    alert(`Đã lọc dữ liệu từ ${this.state.fromDate} đến ${this.state.toDate}`);
  };

  render() {
    const { fromDate, toDate, stats, topProducts } = this.state;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>HỆ THỐNG BÁO CÁO & THỐNG KÊ</h3>

        {/* 1. Thanh lọc thời gian */}
        <div style={{ backgroundColor: '#FFF', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '15px' }}>
          <span><b>Đơn hàng được tạo từ:</b></span>
          <input
            type="date"
            style={{ padding: '8px', borderRadius: '6px', border: '1px solid #CCC' }}
            value={fromDate}
            onChange={(e) => this.setState({ fromDate: e.target.value })}
          />
          <span><b>đến</b></span>
          <input
            type="date"
            style={{ padding: '8px', borderRadius: '6px', border: '1px solid #CCC' }}
            value={toDate}
            onChange={(e) => this.setState({ toDate: e.target.value })}
          />
          <button
            onClick={this.btnFilterClick}
            style={{ backgroundColor: '#4A2E2B', color: '#FFF', border: 'none', padding: '8px 20px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}
          >
            Lọc dữ liệu
          </button>
        </div>

        {/* 2. Các thẻ chỉ số chính (Summary Cards) */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '20px' }}>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Doanh thu</div>
            <div style={{ ...styles.cardValue, color: '#2E7D32' }}>
              {stats.revenue ? stats.revenue.toLocaleString('vi-VN') + ' đ' : '120.500.000 đ'}
            </div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Đơn hàng</div>
            <div style={{ ...styles.cardValue, color: '#1E88E5' }}>{stats.orders || 150} đơn</div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Khách hàng</div>
            <div style={{ ...styles.cardValue, color: '#C85A32' }}>{stats.customers || 85} khách</div>
          </div>
          <div style={styles.card}>
            <div style={styles.cardTitle}>Sản phẩm</div>
            <div style={{ ...styles.cardValue, color: '#6A1B9A' }}>{stats.products || 32} món</div>
          </div>
        </div>

        {/* 3. Khu vực Biểu đồ & Yêu cầu hỗ trợ */}
        <div style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
          {/* Khung mô phỏng biểu đồ doanh thu */}
          <div style={{ flex: '2', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>Biểu đồ doanh thu (Đơn vị: triệu VNĐ)</h4>
            <div style={{ height: '200px', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', padding: '10px 20px', backgroundColor: '#FAFAFA', borderRadius: '8px', border: '1px solid #EEE' }}>
              <div style={{ ...styles.chartBar, height: '40%' }}><span style={styles.barLabel}>T2</span></div>
              <div style={{ ...styles.chartBar, height: '65%' }}><span style={styles.barLabel}>T3</span></div>
              <div style={{ ...styles.chartBar, height: '50%' }}><span style={styles.barLabel}>T4</span></div>
              <div style={{ ...styles.chartBar, height: '85%' }}><span style={styles.barLabel}>T5</span></div>
              <div style={{ ...styles.chartBar, height: '70%' }}><span style={styles.barLabel}>T6</span></div>
              <div style={{ ...styles.chartBar, height: '95%' }}><span style={styles.barLabel}>T7</span></div>
              <div style={{ ...styles.chartBar, height: '90%' }}><span style={styles.barLabel}>CN</span></div>
            </div>
          </div>

          {/* Món ăn gọi nhiều & Hỗ trợ */}
          <div style={{ flex: '1', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px', color: '#4A2E2B' }}>Thông báo & Yêu cầu bàn</h4>
            <div style={{ fontSize: '13px', lineHeight: '1.8' }}>
              <div style={{ padding: '8px', backgroundColor: '#FFF8E1', borderRadius: '6px', marginBottom: '8px' }}>
                <b>Bàn 03:</b> Yêu cầu thanh toán
              </div>
              <div style={{ padding: '8px', backgroundColor: '#E3F2FD', borderRadius: '6px', marginBottom: '8px' }}>
                <b>Bàn 05:</b> Gọi nhân viên phục vụ
              </div>
              <div style={{ padding: '8px', backgroundColor: '#F1F8E9', borderRadius: '6px' }}>
                <b>Bàn 01:</b> Đã đặt thêm 2 món
              </div>
            </div>
          </div>
        </div>

        {/* 4. Top món ăn bán chạy nhất */}
        <div style={{ backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
          <h4 style={{ marginBottom: '15px' }}>Top món ăn bán chạy nhất</h4>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px' }}>
            {topProducts.map((item, index) => (
              <div key={item._id || index} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px', border: '1px solid #EEE', borderRadius: '8px', backgroundColor: '#FAFAFA' }}>
                {item.image ? (
                  <img src={item.image} alt={item.name} style={{ width: '50px', height: '50px', objectFit: 'cover', borderRadius: '6px' }} />
                ) : (
                  <div style={{ width: '50px', height: '50px', backgroundColor: '#C85A32', color: '#FFF', borderRadius: '6px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>
                    #{index + 1}
                  </div>
                )}
                <div>
                  <div style={{ fontWeight: 'bold', fontSize: '14px' }}>{item.name}</div>
                  <div style={{ color: '#C85A32', fontSize: '13px', fontWeight: 'bold' }}>
                    {item.price ? item.price.toLocaleString('vi-VN') + ' đ' : '45.000 đ'}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

      </div>
    );
  }
}

const styles = {
  card: {
    backgroundColor: '#FFF',
    padding: '16px',
    borderRadius: '12px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
    textAlign: 'center'
  },
  cardTitle: {
    fontSize: '13px',
    color: '#666',
    marginBottom: '6px'
  },
  cardValue: {
    fontSize: '20px',
    fontWeight: 'bold'
  },
  chartBar: {
    width: '30px',
    backgroundColor: '#4A2E2B',
    borderRadius: '6px 6px 0 0',
    position: 'relative',
    display: 'flex',
    justifyContent: 'center'
  },
  barLabel: {
    position: 'absolute',
    bottom: '-22px',
    fontSize: '12px',
    color: '#666',
    fontWeight: 'bold'
  }
};

export default ReportComponent;
